include <robotics.scad>
// HC-SR04 PCB, origin = board centre at bottom face.
L = 45;      // datasheet 45*20*15 (Cytron drawing shows 43)
W = 20;      // datasheet
T = 1.6;     // assumed standard FR4
hole_dx = 40;   // Cytron drawing, c-c along length
hole_dy = 15;   // NOT dimensioned - scaled from Cytron drawing
hole_d  = 2.0;  // NOT dimensioned - conservative
$fn = 32;
diff() cuboid([L, W, T], anchor = BOT) {
  tag("remove") grid_copies(spacing = [hole_dx, hole_dy], n = [2, 2]) cyl(d = hole_d, h = T + 1);
  // 4 plated through-holes for the header, 2.54 pitch, at the -Y edge
  tag("remove") fwd(W/2 - 1.6) xcopies(2.54, n = 4) cyl(d = 1.0, h = T + 1);
}

include <robotics.scad>
// Transducer can, origin = centre of base on PCB top face.
d = 16;          // NOT dimensioned (unofficial ~16)
h = 15 - 1.6;    // top flush with 15 mm datasheet depth
cyl(d = d, h = h, chamfer2 = 0.4, anchor = BOT, $fn = 64);

include <robotics.scad>
// Transducer can, origin = centre of base on PCB top face.
d = 16;          // NOT dimensioned (unofficial ~16)
h = 15 - 1.6;    // top flush with 15 mm datasheet depth
cyl(d = d, h = h, chamfer2 = 0.4, anchor = BOT, $fn = 64);

include <robotics.scad>
// 4 MHz crystal lying flat, plain envelope.
cuboid([10, 4, 3.5], rounding = 1.5, edges = "Z", anchor = BOT, $fn = 32);

include <robotics.scad>
// Origin = pin row centre on PCB top face (pins at y_board = -8.4).
p = 2.54; n = 4;
body = [n*p, 2.5, 2.5];
pin = 0.64;
out = 6;   // estimated protrusion beyond board edge
union() {
  cuboid(body, anchor = BOT);                       // plastic spacer
  xcopies(p, n = n) {
    down(1.6) cuboid([pin, pin, 1.6 + body.z/2 + pin/2], anchor = BOT);  // leg through board, flush at back
    up(body.z/2) cuboid([pin, 1.6 + out, pin], anchor = BACK + CENTER);  // leg toward -Y
  }
}
